"""Builds each sandbox experiment's figures.js from the shared stage kit and its own body.

    python3 ch99/_kit/build.py

kit.js and the NN.N.js files beside it are the sources; ch99/NN.N/figures.js is written from them.
"""
import pathlib
here = pathlib.Path(__file__).parent
kit = (here / "kit.js").read_text()
for body in sorted(here.glob("99.*.js")):
    sec = body.stem
    out = here.parent / sec / "figures.js"
    out.parent.mkdir(exist_ok=True)
    out.write_text(
        "/* SANDBOX, not part of the book. GENERATED by ch99/_kit/build.py from _kit/kit.js and _kit/%s.js: edit those. */\n"
        "window.OMNISTAX_FIGURES = window.OMNISTAX_FIGURES || {};\n"
        "window.OMNISTAX_FIGURES['%s'] = function (root, F) {\n%s\n%s};\n" % (sec, sec, kit, body.read_text())
    )
    print("wrote", out.relative_to(here.parent.parent))
